#!/usr/bin/env node
// Regenerates every file derived from schema/pplf.schema.json.
//   node tools/build/generate.mjs          write files
//   node tools/build/generate.mjs --check  fail if any generated file is out of date (used in CI)

import { readFile, writeFile, mkdir, readdir, rm } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import { buildFlows, flowFileName, spListDefinitions } from './flows.mjs';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const check = process.argv.includes('--check');
const HEADER = 'GENERATED by tools/build/generate.mjs from schema/pplf.schema.json. Do not edit by hand.';

const stale = [];

async function emit(rel, content) {
  const file = path.join(root, rel);
  let current = null;
  try { current = await readFile(file, 'utf8'); } catch { /* new file */ }
  if (current === content) return;
  if (check) { stale.push(rel); return; }
  await mkdir(path.dirname(file), { recursive: true });
  await writeFile(file, content);
  console.log(`wrote ${rel}`);
}

const json = (o) => JSON.stringify(o, null, 2) + '\n';

function schemaMarkdown(schema) {
  const lines = [`<!-- ${HEADER} -->`, '', '# Schema reference', '',
    `Schema version **${schema.version}**. Publisher prefix \`${schema.publisher.customizationPrefix}\`, choice value prefix \`${schema.publisher.customizationOptionValuePrefix}\`.`, '',
    'The same columns exist in Dataverse and SharePoint, so you can switch the log target without changing reports or queries.', '',
    '## Log levels', '', '| Level | Severity | Choice value |', '|---|---|---|',
    ...schema.levels.map((l) => `| ${l.name} | ${l.severity} | ${l.value} |`), ''];
  for (const t of schema.tables) {
    lines.push(`## ${t.displayName} (\`${t.logicalName}\`)`, '', t.description, '',
      `SharePoint list: **${t.sharePointList.title}** (URL \`/Lists/${t.sharePointList.url}\`)`, '',
      '| Display name | Dataverse column | Type | SharePoint field | SP type | Indexed | Notes |', '|---|---|---|---|---|---|---|',
      `| ${t.primaryName.displayName} | \`${t.primaryName.schemaName.toLowerCase()}\` | Text(${t.primaryName.maxLength}) | \`Title\` | Text | | ${t.primaryName.description} |`);
    for (const c of t.columns) {
      const type = c.type === 'Choice' ? `Choice (\`${c.globalChoice}\`)` : c.maxLength ? `${c.type}(${c.maxLength})` : c.type;
      lines.push(`| ${c.displayName} | \`${c.schemaName.toLowerCase()}\` | ${type}${c.required ? ' *' : ''} | \`${c.sp.internalName}\` | ${c.sp.type} | ${c.sp.indexed ? 'yes' : ''} | ${c.description || ''} |`);
    }
    lines.push('', '\\* required', '');
  }
  lines.push('## Environment variables', '', '| Schema name | Type | Default | Allowed | Purpose |', '|---|---|---|---|---|',
    ...schema.environmentVariables.map((e) => `| \`${e.schemaName}\` | ${e.type} | ${e.default ? `\`${e.default}\`` : ''} | ${e.allowed ? e.allowed.join(', ') : ''} | ${e.description} |`), '',
    '## Connection references', '', '| Logical name | Connector |', '|---|---|',
    ...schema.connectionReferences.map((c) => `| \`${c.logicalName}\` | \`${c.connectorId.split('/').pop()}\` |`), '',
    '## Security roles', '');
  for (const r of schema.securityRoles) {
    lines.push(`**${r.name}**: ${r.description}`, '', ...r.privileges.map((p) => `- \`${p.table}\`: ${p.rights.join(', ')} (${p.depth})`), '');
  }
  return lines.join('\n');
}

async function main() {
  const schema = JSON.parse(await readFile(path.join(root, 'schema', 'pplf.schema.json'), 'utf8'));

  // 1. Flows
  const flows = buildFlows(schema);
  const expected = new Set();
  for (const f of flows) {
    const name = flowFileName(f.name);
    expected.add(name);
    await emit(`src/flows/${name}`, json({ $comment: HEADER, ...f }));
  }
  if (!check) {
    for (const f of await readdir(path.join(root, 'src', 'flows'))) {
      if (f.endsWith('.json') && !expected.has(f)) { await rm(path.join(root, 'src', 'flows', f)); console.log(`removed src/flows/${f}`); }
    }
  }

  // 2. SharePoint list definitions (used by tools/sharepoint and docs)
  await emit('src/sharepoint/lists.json', json({ $comment: HEADER, lists: spListDefinitions(schema) }));

  // 3. Browser bundle of the deployer, with schema and flows embedded
  const lib = await readFile(path.join(root, 'tools', 'deployer', 'pplf-deployer.mjs'), 'utf8');
  const sp = await readFile(path.join(root, 'tools', 'sharepoint', 'pplf-sharepoint.mjs'), 'utf8');
  const strip = (s) => s.replace(/^export (async function|function|const)/gm, '$1').replace(/^import .*$/gm, '');
  const bundle = `// ${HEADER}
// Paste into the browser dev tools console while signed in to your Dataverse environment
// (https://<org>.crm.dynamics.com), then run:   await PplfDeployer.deploy()
// On a SharePoint site page run:                 await PplfDeployer.provisionSharePoint()
(() => {
${strip(lib)}
${strip(sp)}
const SCHEMA = ${JSON.stringify(schema)};
const FLOWS = ${JSON.stringify(flows.map((f) => ({ name: f.name, description: f.description, clientdata: f.clientdata })))};
const client = () => createClient({ envUrl: location.origin, solution: SCHEMA.solution.uniqueName });
window.PplfDeployer = {
  schema: SCHEMA,
  flows: FLOWS,
  deploy: (opts = {}) => deploy({ client: client(), schema: SCHEMA, flows: FLOWS, ...opts }),
  activate: () => activateFlows(client(), FLOWS),
  setTarget: (target) => setEnvironmentVariableValue(client(), 'pplf_LogTarget', target),
  setValue: (schemaName, value) => setEnvironmentVariableValue(client(), schemaName, value),
  bind: (bindings) => bindConnections(client(), bindings),
  provisionSharePoint: (siteUrl = window._spPageContextInfo?.webAbsoluteUrl || location.origin) => provisionLists({ siteUrl, lists: spListDefinitions_(SCHEMA) })
};
function spListDefinitions_(schema) { return ${JSON.stringify(spListDefinitions(schema))}; }
console.log('PplfDeployer ready. Run: await PplfDeployer.deploy()');
})();
`;
  await emit('dist/pplf-deployer.browser.js', bundle);

  // 4. Docs
  await emit('docs/reference/schema.md', schemaMarkdown(schema));

  if (check && stale.length) {
    console.error(`Generated files are out of date. Run "npm run build" and commit:\n  ${stale.join('\n  ')}`);
    process.exit(1);
  }
  if (check) console.log('Generated files are up to date.');
}

main().catch((e) => { console.error(e); process.exit(1); });
